import React from 'react';
import { 
  LayoutDashboard, ShoppingBag, Package, Shield, Users, 
  LogOut, ShieldCheck, User as UserIcon,
  FileCheck, BadgeCheck, Cpu, Video, Settings
} from 'lucide-react';
import { User } from '../../types';

// Updated Tab type to include missing values 'blog', 'liked', and 'moderation' used in Dashboard.tsx
export type Tab = 'overview' | 'orders' | 'inventory' | 'manage_courses' | 'manage_products' | 'users' | 'verification' | 'admin_verifications' | 'admin_profiles' | 'profile' | 'expert_systems' | 'settings' | 'blog' | 'liked' | 'moderation';

interface DashboardSidebarProps {
  user: User;
  activeTab: Tab;
  setActiveTab: (tab: Tab) => void;
  onLogout: () => void;
}

const DashboardSidebar: React.FC<DashboardSidebarProps> = ({ user, activeTab, setActiveTab, onLogout }) => {
  const SidebarItem = ({ id, label, icon: Icon }: { id: Tab; label: string; icon: any }) => (
    <button
      onClick={() => setActiveTab(id)}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-bold transition-colors ${
        activeTab === id
          ? 'bg-emerald-600 text-white shadow-md shadow-emerald-600/20'
          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-white'
      }`}
    >
      <Icon size={18} />
      {label}
    </button>
  );

  const isSeller = user.role === 'admin' || user.role === 'moderator';

  return (
    <aside className="w-full h-full flex flex-col">
      <div className="p-6">
        <div className="flex items-center gap-3 mb-8">
          <div className="w-12 h-12 rounded-full bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-xl overflow-hidden relative group shrink-0 border-2 border-white dark:border-slate-800">
            {user.profilePic ? (
                <img src={user.profilePic} alt="Profile" className="w-full h-full object-cover" />
            ) : (
                <span>{user.firstName[0]}</span>
            )}
          </div>
          <div className="overflow-hidden">
            <h3 className="font-bold text-slate-900 dark:text-white truncate text-sm" title={`${user.firstName} ${user.lastName}`}>
                {user.firstName} {user.lastName}
            </h3>
            <p className="text-[10px] uppercase font-black text-emerald-600 truncate">
                {user.role} Member
            </p>
          </div>
        </div>

        <nav className="space-y-1">
          <h4 className="px-4 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Personal</h4>
          <SidebarItem id="overview" label="Dashboard" icon={LayoutDashboard} />
          <SidebarItem id="inventory" label="Purchased Tools" icon={Package} />
          <SidebarItem id="orders" label="Order History" icon={ShoppingBag} />
          <SidebarItem id="profile" label="My Profile" icon={UserIcon} />
          <SidebarItem id="verification" label="Account ID" icon={ShieldCheck} />
          
          {isSeller && (
            <>
              <div className="my-4 border-t border-slate-100 dark:border-slate-800"></div>
              <h4 className="px-4 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Creator Studio</h4>
              <SidebarItem id="manage_courses" label="My Courses" icon={Video} />
              <SidebarItem id="manage_products" label="My Products" icon={Package} />
            </>
          )}
          
          {user.role === 'admin' && (
            <>
              <div className="my-4 border-t border-slate-100 dark:border-slate-800"></div>
              <h4 className="px-4 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Store Admin</h4>
              <SidebarItem id="admin_verifications" label="ID Verifications" icon={FileCheck} />
              <SidebarItem id="expert_systems" label="License Control" icon={Cpu} />
              <SidebarItem id="users" label="User Manager" icon={Users} />
              <SidebarItem id="settings" label="Store Settings" icon={Settings} />
            </>
          )}
        </nav>
      </div>

      <div className="mt-auto p-6 border-t border-slate-100 dark:border-slate-800">
        <button 
          onClick={onLogout}
          className="w-full flex items-center gap-3 px-4 py-2 text-sm font-bold text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
        >
          <LogOut size={18} /> Sign Out
        </button>
      </div>
    </aside>
  );
};

export default DashboardSidebar;