import { VerificationState, AdminVerificationRequest } from '../types';
import { getApiOrigin } from './config';

const API_URL = `${getApiOrigin()}/auth/verify`;

const getHeaders = () => {
  return {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
};

const handleResponse = async (res: Response) => {
  const contentType = res.headers.get("content-type");
  if (contentType && contentType.includes("application/json")) {
    const json = await res.json();
    if (!res.ok) {
      throw new Error(json.message || `API Error: ${res.status}`);
    }
    return json;
  } else {
    const text = await res.text();
    console.error(`Non-JSON response from ${res.url}:`, text.substring(0, 100));
    throw new Error(`API Error: ${res.status} (Invalid Response Format)`);
  }
};

// Helper to map raw backend verification object to frontend VerificationState
const mapToState = (data: any): VerificationState => {
  // Handle if data is wrapped in { verification: ... } or is the verification object itself
  const v = data.verification || data;
  
  // Default fallback if v is missing
  if (!v || typeof v !== 'object') {
      return {
          status: 'UNVERIFIED',
          emailVerified: false,
          identityVerified: false,
          identityStatus: 'unverified'
      } as any;
  }

  let idStatus: 'unverified' | 'pending' | 'verified' | 'rejected' = 'unverified';
  
  if (v.identity?.verified) {
      idStatus = 'verified';
  } else if (v.rejectionReason) {
      // If rejected, check if we want to show 'rejected' state. 
      // Usually if overall is not PENDING, it's rejected.
      idStatus = 'rejected';
  } else if (v.identity?.documentKey || v.identity?.documentUrl) {
      idStatus = 'pending';
  }

  return {
    status: v.overall || 'UNVERIFIED',
    emailVerified: !!v.email?.verified,
    identityVerified: !!v.identity?.verified,
    identityStatus: idStatus,
    rejectionReason: v.rejectionReason,
    updatedAt: v.identity?.verifiedAt || v.email?.verifiedAt
  };
};

export const verificationApi = {
  // User: Get current status
  getStatus: async (): Promise<VerificationState> => {
    try {
      const res = await fetch(`${API_URL}/status`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      const json = await handleResponse(res);
      return mapToState(json);
    } catch (error) {
      console.error('Fetch status failed:', error);
      throw error;
    }
  },

  // User: Send Email OTP
  sendEmailOtp: async (): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/email/send-otp`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({})
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw new Error(error.message || 'Failed to send OTP');
    }
  },

  // User: Confirm Email OTP
  confirmEmailOtp: async (otp: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/email/confirm-otp`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ otp })
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw new Error(error.message || 'Invalid OTP');
    }
  },

  // User: Upload Identity Document
  uploadIdentity: async (file: File): Promise<{ success: boolean; message: string }> => {
    const formData = new FormData();
    formData.append('document', file);

    try {
      // Note: Don't use standard getHeaders() here because Content-Type is multipart/form-data
      // Browser sets boundary automatically when using FormData
      const res = await fetch(`${API_URL}/identity/upload`, {
        method: 'POST',
        headers: {
            'Accept': 'application/json'
        },
        mode: 'cors',
        credentials: 'include',
        body: formData
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw new Error(error.message || 'Upload failed');
    }
  },

  // Admin: Get Pending Verifications
  getPendingRequests: async (): Promise<AdminVerificationRequest[]> => {
    try {
      const url = `${API_URL}/identity/pending`;
      const res = await fetch(url, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      const json = await handleResponse(res);
      return json;
    } catch (error) {
      console.error('[VerificationAPI] Fetch pending failed:', error);
      return [];
    }
  },

  // Admin: Get Presigned URL for Document
  getPresignedUrl: async (userId: string): Promise<{ url: string }> => {
    try {
      const res = await fetch(`${API_URL}/identity/${userId}/presign`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      const json = await handleResponse(res);
      // Map backend 'presignedUrl' to frontend expected 'url'
      return { url: json.presignedUrl };
    } catch (error: any) {
      throw new Error(error.message || 'Failed to get document URL');
    }
  },

  // Admin: Approve Identity
  approveIdentity: async (userId: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/identity/${userId}/approve`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({})
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw new Error(error.message || 'Action failed');
    }
  },

  // Admin: Reject Identity
  rejectIdentity: async (userId: string, reason: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/identity/${userId}/reject`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ reason })
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw new Error(error.message || 'Action failed');
    }
  }
};
