
import React, { useState, useEffect } from 'react';
import { User, BlogPost } from '../../types';
import { userApi } from '../../api/user';
import { blogApi } from '../../api/blog';
import { Loader2, ArrowLeft, Eye, ShieldCheck, Search, X, User as UserIcon, Calendar, FileText } from 'lucide-react';
import ConfirmModal from '../ConfirmModal';

interface AdminUsersSectionProps {
  onNotify: (type: 'success' | 'error', message: string) => void;
  onViewPost: (post: BlogPost) => void;
}

const AdminUsersSection: React.FC<AdminUsersSectionProps> = ({ onNotify, onViewPost }) => {
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [inspectingUser, setInspectingUser] = useState<User | null>(null);
  const [inspectingPosts, setInspectingPosts] = useState<{ public: BlogPost[], pending: BlogPost[], rejected: BlogPost[] }>({ public: [], pending: [], rejected: [] });
  const [loadingInspection, setLoadingInspection] = useState(false);
  const [actionLoading, setActionLoading] = useState<Record<string, boolean>>({});
  const [confirmModal, setConfirmModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; isLoading?: boolean }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

  useEffect(() => {
      fetchUsers();
  }, []);

  const fetchUsers = async () => {
      setLoading(true);
      try {
          const data = await userApi.getAll();
          setAllUsers(Array.isArray(data) ? data : []);
      } catch(e) {
          console.error(e);
          onNotify('error', 'Failed to load users');
      } finally {
          setLoading(false);
      }
  };

  const filteredUsers = allUsers.filter(u => 
      `${u.firstName} ${u.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
      u.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (u.username && u.username.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const initiateRoleChange = (userId: string, newRole: string) => {
     setConfirmModal({
         isOpen: true,
         title: 'Change User Role',
         message: `Are you sure you want to change this user's role to ${newRole}?`,
         isLoading: false,
         onConfirm: async () => {
             setConfirmModal(prev => ({ ...prev, isLoading: true }));
             setActionLoading(prev => ({ ...prev, [`role-${userId}`]: true }));
             try {
                const res = await userApi.updateRole(userId, newRole);
                if(res.success) {
                    onNotify('success', res.message);
                    setAllUsers(prev => prev.map(u => (u._id === userId || u.user_id === userId) ? { ...u, role: newRole as any } : u));
                    setConfirmModal(prev => ({ ...prev, isOpen: false }));
                } else {
                    onNotify('error', res.message);
                    setConfirmModal(prev => ({ ...prev, isLoading: false }));
                }
             } catch (e: any) {
                onNotify('error', e.message || "Failed to update role");
                setConfirmModal(prev => ({ ...prev, isLoading: false }));
             } finally {
                setActionLoading(prev => ({ ...prev, [`role-${userId}`]: false }));
             }
         }
     });
  };

  const handleInspectUser = async (targetUser: User) => {
      setInspectingUser(targetUser);
      setLoadingInspection(true);
      try {
          const [pub, modQueue] = await Promise.all([
              blogApi.getAllPublic(),
              blogApi.getModerationPosts().catch(() => []) // Catch if mod queue fails
          ]);
          
          const targetId = targetUser._id || targetUser.user_id;
          
          const isTarget = (p: BlogPost) => {
              const authorId = typeof p.authorId === 'object' && p.authorId ? (p.authorId._id || (p.authorId as any).user_id) : p.authorId;
              return String(authorId) === String(targetId);
          }
          
          const userPub = pub.filter(isTarget);
          const userMod = modQueue.filter(isTarget);
          const userPend = userMod.filter(p => p.visibility === 'pending');
          const userRej = userMod.filter(p => p.visibility === 'rejected');
          
          setInspectingPosts({ public: userPub, pending: userPend, rejected: userRej });
      } catch (e) {
          console.error("Error inspecting user", e);
          onNotify('error', "Failed to load user activity");
      } finally {
          setLoadingInspection(false);
      }
  };

  return (
    <div className="space-y-6">
        <ConfirmModal 
            isOpen={confirmModal.isOpen} 
            title={confirmModal.title} 
            message={confirmModal.message} 
            isLoading={confirmModal.isLoading}
            onClose={() => setConfirmModal(prev => ({ ...prev, isOpen: false }))} 
            onConfirm={confirmModal.onConfirm}
        />

        {!inspectingUser ? (
            <div className="space-y-6">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                    <h2 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">User Manager</h2>
                    <div className="relative w-full sm:w-64 group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-emerald-500 transition-colors" size={16}/>
                        <input 
                            type="text" 
                            placeholder="Search users..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 text-sm dark:text-white shadow-sm"
                        />
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left min-w-[700px]">
                            <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 text-[10px] uppercase font-black tracking-widest">
                                <tr>
                                    <th className="px-6 py-4">User Identity</th>
                                    <th className="px-6 py-4">Security Role</th>
                                    <th className="px-6 py-4">Account Age</th>
                                    <th className="px-6 py-4 text-right">Activity</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {loading ? (
                                    <tr><td colSpan={4} className="px-6 py-12 text-center"><Loader2 className="animate-spin mx-auto text-emerald-600"/></td></tr>
                                ) : filteredUsers.length === 0 ? (
                                    <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-500 font-bold uppercase text-[10px] tracking-widest">No matching users found.</td></tr>
                                ) : filteredUsers.map(u => (
                                    <tr key={u._id || u.user_id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-bold text-slate-500 border-2 border-white dark:border-slate-700 overflow-hidden">
                                                    {u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover"/> : <span>{u.firstName[0]}</span>}
                                                </div>
                                                <div>
                                                    <div className="font-bold text-slate-900 dark:text-white text-sm">{u.firstName} {u.lastName}</div>
                                                    <div className="text-xs text-slate-500 font-medium">{u.email}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-2">
                                                <select 
                                                    value={u.role || 'user'}
                                                    onChange={(e) => initiateRoleChange((u._id || u.user_id)!, e.target.value)}
                                                    disabled={actionLoading[`role-${u._id || u.user_id}`]}
                                                    className="bg-slate-100 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-1.5 text-xs font-black uppercase text-slate-700 dark:text-slate-300 outline-none focus:ring-2 focus:ring-emerald-500 transition-all cursor-pointer"
                                                >
                                                    <option value="user">User</option>
                                                    <option value="moderator">Moderator</option>
                                                    <option value="admin">Admin</option>
                                                </select>
                                                {actionLoading[`role-${u._id || u.user_id}`] && <Loader2 className="animate-spin text-emerald-600" size={12}/>}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-2 text-xs font-bold text-slate-500">
                                                <Calendar size={14} className="opacity-50"/>
                                                {u.createdAt ? new Date(u.createdAt).toLocaleDateString() : 'N/A'}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button 
                                                onClick={() => handleInspectUser(u)}
                                                className="px-3 py-1.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 rounded-lg text-xs font-black uppercase hover:bg-emerald-100 dark:hover:bg-emerald-900/40 transition-colors"
                                            >
                                                Inspect
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        ) : (
            <div className="space-y-8">
                <div className="flex flex-col sm:flex-row items-center gap-6 pb-6 border-b border-slate-200 dark:border-slate-800">
                    <button onClick={() => setInspectingUser(null)} className="p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-slate-500 shadow-sm">
                        <ArrowLeft size={20} />
                    </button>
                    <div className="flex items-center gap-4 flex-1">
                        <div className="w-16 h-16 rounded-3xl bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center font-bold text-2xl text-emerald-600 border-2 border-white dark:border-slate-800 overflow-hidden">
                             {inspectingUser.profilePic ? <img src={inspectingUser.profilePic} className="w-full h-full object-cover"/> : <span>{inspectingUser.firstName[0]}</span>}
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">{inspectingUser.firstName} {inspectingUser.lastName}</h2>
                            <div className="flex flex-wrap gap-3 mt-1">
                                <span className="flex items-center gap-1.5 text-xs font-bold text-slate-500"><UserIcon size={12}/> {inspectingUser.email}</span>
                                <span className="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded text-[10px] font-black uppercase text-slate-600 dark:text-slate-400">{inspectingUser.role}</span>
                            </div>
                        </div>
                    </div>
                </div>

                {loadingInspection ? (
                    <div className="flex flex-col items-center justify-center py-20 gap-4">
                        <Loader2 className="animate-spin text-emerald-600" size={32}/>
                        <p className="text-xs font-black uppercase tracking-widest text-slate-400">Loading activity logs...</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                        {/* Stats Cards */}
                        <div className="lg:col-span-1 space-y-4">
                             <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                                <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Activity Score</h4>
                                <div className="space-y-4">
                                    <div className="flex justify-between items-center">
                                        <span className="text-sm font-bold text-slate-600 dark:text-slate-400">Public Articles</span>
                                        <span className="text-xl font-black text-slate-900 dark:text-white">{inspectingPosts.public.length}</span>
                                    </div>
                                    <div className="flex justify-between items-center">
                                        <span className="text-sm font-bold text-slate-600 dark:text-slate-400">Pending Review</span>
                                        <span className="text-xl font-black text-amber-500">{inspectingPosts.pending.length}</span>
                                    </div>
                                    <div className="flex justify-between items-center">
                                        <span className="text-sm font-bold text-slate-600 dark:text-slate-400">Total Rejected</span>
                                        <span className="text-xl font-black text-red-500">{inspectingPosts.rejected.length}</span>
                                    </div>
                                </div>
                             </div>
                        </div>

                        {/* Recent Activity */}
                        <div className="lg:col-span-2 space-y-6">
                            <h3 className="text-lg font-black text-slate-900 dark:text-white uppercase tracking-tight flex items-center gap-2">
                                <FileText size={18} className="text-emerald-500"/> Content History
                            </h3>
                            
                            <div className="space-y-3">
                                {[...inspectingPosts.public, ...inspectingPosts.pending, ...inspectingPosts.rejected].length === 0 ? (
                                    <div className="py-20 text-center bg-slate-50 dark:bg-slate-950 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-800">
                                        <p className="text-slate-500 font-bold uppercase text-xs">No contribution history found.</p>
                                    </div>
                                ) : (
                                    [...inspectingPosts.public, ...inspectingPosts.pending, ...inspectingPosts.rejected]
                                        .sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
                                        .map(p => (
                                            <button 
                                                key={p._id}
                                                onClick={() => onViewPost(p)}
                                                className="w-full text-left p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl hover:border-emerald-500/50 transition-all flex items-center justify-between group shadow-sm"
                                            >
                                                <div className="min-w-0 flex-1 pr-4">
                                                    <div className="font-bold text-slate-900 dark:text-white text-sm truncate group-hover:text-emerald-600 transition-colors">{p.title}</div>
                                                    <div className="text-[10px] text-slate-500 mt-1 uppercase font-bold tracking-tight">{new Date(p.createdAt).toLocaleDateString()}</div>
                                                </div>
                                                <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase shrink-0 ${
                                                    p.visibility === 'public' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30' :
                                                    p.visibility === 'pending' ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/30' :
                                                    'bg-red-100 text-red-700 dark:bg-red-900/30'
                                                }`}>
                                                    {p.visibility}
                                                </span>
                                            </button>
                                        ))
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        )}
    </div>
  );
};

export default AdminUsersSection;
