import { ExpertUserDesc, ExpertStats, ExpertDefinition, UserSearchResult } from '../types';
import { getApiOrigin } from './config';

const API_URL = `${getApiOrigin()}/api/expert/admin`;

const getHeaders = () => {
  return {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
};

const handleResponse = async (res: Response) => {
  const contentType = res.headers.get("content-type");
  if (contentType && contentType.includes("application/json")) {
    const json = await res.json();
    if (!res.ok) {
      if (json.results || json.details) return json;
      throw new Error(json.message || `API Error: ${res.status}`);
    }
    return json;
  } else {
    const text = await res.text();
    console.error(`Non-JSON response from ${res.url}:`, text.substring(0, 100));
    throw new Error(`API Error: ${res.status} (Invalid Response Format)`);
  }
};

export const expertApi = {
  getAvailableExperts: async (): Promise<{ success: boolean; experts: ExpertDefinition[] }> => {
    try {
      const res = await fetch(`${API_URL}/available-experts`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      return await handleResponse(res);
    } catch (error: any) {
      console.warn("Using fallback experts list");
      return { 
        success: true, 
        experts: [
          { expertId: 'EA_TREND_01', expertName: 'TrendScout Pro', description: 'Trend following EA', isActive: true },
          { expertId: 'EA_SCALP_X', expertName: 'Scalp Master X', description: 'High frequency scalper', isActive: true },
          { expertId: 'EA_GRID_V2', expertName: 'Grid Logic V2', description: 'Grid system with hedging', isActive: false }
        ] 
      };
    }
  },

  addExpert: async (data: {
    expertId?: string;
    name?: string;
    description?: string;
    metadata?: any;
    isActive?: boolean;
    items?: any[];
  }): Promise<{ success: boolean; message?: string; expert?: ExpertDefinition; results?: any[]; details?: any[] }> => {
    try {
      const res = await fetch(`${API_URL}/add-expert`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify(data)
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw error;
    }
  },

  searchUsers: async (query: string, page = 1, limit = 20): Promise<{ success: boolean; users: UserSearchResult[]; total: number }> => {
    try {
      const params = new URLSearchParams({
        q: query,
        page: String(page),
        limit: String(limit)
      });
      
      const res = await fetch(`${API_URL}/users-search?${params.toString()}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      return await handleResponse(res);
    } catch (error: any) {
      console.error("User search error:", error);
      return { success: false, users: [], total: 0 };
    }
  },

  // POST /api/expert/admin/add-user (Granting access)
  addUser: async (data: { 
    items?: any[];      // Supports batch with updates object inside
    atomic?: boolean;
    userEmail?: string; 
    expertId?: string; 
    expertName?: string; 
    updates?: Record<string, any>; // Nested updates
  }): Promise<{ success: boolean; message: string; userData?: any; results?: any[] }> => {
    try {
      const res = await fetch(`${API_URL}/add-user`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify(data)
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw error;
    }
  },

  removeUser: async (userEmail: string, expertId: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/remove-user`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ userEmail, expertId })
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw error;
    }
  },

  // POST /api/expert/admin/update-user
  updateUser: async (userEmail: string, expertId: string, updates: Record<string, any>): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/update-user`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ userEmail, expertId, updates })
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw error;
    }
  },

  getUsers: async (filters?: { expertId?: string; licenseType?: string; isActive?: boolean }): Promise<{ success: boolean; count: number; users: ExpertUserDesc[] }> => {
    try {
      const queryParams = new URLSearchParams();
      if (filters?.expertId) queryParams.append('expertId', filters.expertId);
      if (filters?.licenseType) queryParams.append('licenseType', filters.licenseType);
      if (filters?.isActive !== undefined) queryParams.append('isActive', String(filters.isActive));

      const res = await fetch(`${API_URL}/users?${queryParams.toString()}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      return await handleResponse(res);
    } catch (error: any) {
      console.error('Fetch expert users failed:', error);
      throw error;
    }
  },

  getUserDetails: async (email: string): Promise<{ success: boolean; user: ExpertUserDesc }> => {
    try {
      const res = await fetch(`${API_URL}/user/${encodeURIComponent(email)}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw error;
    }
  },

  toggleAccess: async (userEmail: string, expertId: string, isActive: boolean): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/toggle-access`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ userEmail, expertId, isActive })
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw error;
    }
  },

  getStats: async (expertId?: string): Promise<{ success: boolean; stats: ExpertStats }> => {
    try {
      const queryParams = new URLSearchParams();
      if (expertId) queryParams.append('expertId', expertId);

      const res = await fetch(`${API_URL}/usage-stats?${queryParams.toString()}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw error;
    }
  }
};
